CREATE TABLE IF NOT EXISTS `playerbot_city` (
  `ZoneId` smallint unsigned NOT NULL DEFAULT '0',
  `CityId` smallint unsigned NOT NULL DEFAULT '0',
  `Minlevel` tinyint unsigned DEFAULT NULL,
  `Maxlevel` tinyint unsigned DEFAULT NULL,
  `TeamsDisabled` smallint unsigned DEFAULT NULL,
  `X` float DEFAULT NULL,
  `Y` float DEFAULT NULL,
  `Z` float DEFAULT NULL,
  `Radius` smallint DEFAULT NULL,
  PRIMARY KEY (`ZoneId`,`CityId`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

DELETE FROM `playerbot_city`;
